function artwork(game){const urls=[];if(game.artwork||game.image)urls.push(game.artwork||game.image);if(game.icon_hash)urls.push(`https://cdn.discordapp.com/app-icons/${game.id}/${game.icon_hash}.png`);if(game.cover_image_hash)urls.push(`https://cdn.discordapp.com/app-assets/${game.id}/store/${game.cover_image_hash}.png`);const steam=(Array.isArray(game.third_party_skus)?game.third_party_skus:[]).find(s=>s.distributor==='steam'&&/^\d+$/.test(s.id));if(steam)urls.push(`https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${steam.id}/header.jpg`);const source=[...new Set(urls)].map(url=>'http://artwork.localhost/?url='+encodeURIComponent(url));const placeholder=`<span class="art-placeholder" ${source.length?'hidden':''}>${getIcon('gamepad')}</span>`;if(!source.length)return placeholder;const first=source.shift();return `<img src="${escapeHtml(first)}" alt="" loading="lazy" data-fallbacks="${escapeHtml(JSON.stringify(source))}">${placeholder}`;}
