function readDuration(hoursInput,minutesInput){if(hoursInput.value===''||minutesInput.value==='')throw new Error('empty');const h=Number(hoursInput.value),m=Number(minutesInput.value);if(!Number.isInteger(h)||!Number.isInteger(m)||h<0||h>24||m<0||m>59||h*60+m>1440)throw new Error('duration');return h*60+m;}
