const canAppend=state.queue?.active&&!state.questQueue?.active;const invalidCustom=state.mode==='custom'&&!validCustomFilename(state.selectedExecutable);const activeDurationMinutes=session?(session.targetDurationSeconds?Math.round(session.targetDurationSeconds/60):0):null;const isDurationChanged=current&&activeDurationMinutes!==null&&state.durationMinutes!==activeDurationMinutes;const toggleBtn=$('btn-toggle-sim'),stopBtn=$('btn-stop-sim');if(current&&!isDurationChanged){toggleBtn.disabled=state.actionBusy||!!state.questQueue?.active;$('btn-sim-text').textContent=t('quest_stop');toggleBtn.classList.add('button-danger');setSlot('btn-sim-icon','square');if(stopBtn)stopBtn.hidden=true;}else if(current&&isDurationChanged){toggleBtn.disabled=state.actionBusy||!!state.questQueue?.active||!state.durationValid||invalidCustom;$('btn-sim-text').textContent=t('start_sim');toggleBtn.classList.remove('button-danger');setSlot('btn-sim-icon','play');if(stopBtn){stopBtn.hidden=false;stopBtn.disabled=state.actionBusy;setSlot('btn-stop-icon','square');}}else{toggleBtn.disabled=state.actionBusy||!!state.questQueue?.active||pending||(!current&&(!state.selectedGame||!state.durationValid||invalidCustom||((session||canAppend)&&state.durationMinutes<1)||(session&&!canAppend)));$('btn-sim-text').textContent=t(pending?'scheduled':session||canAppend?'play_next':'start_sim');toggleBtn.classList.remove('button-danger');setSlot('btn-sim-icon','play');if(stopBtn)stopBtn.hidden=true;}
