async function loadQuests(refresh=false,silent=false){
 if(questsBusy)return;questsBusy=true;const button=$('btn-refresh-quests');busy(button,true);
 try{
  const now=Date.now();
  if(refresh&&!silent&&(now-lastRealQuestFetch<60000)){
   await new Promise(r=>setTimeout(r,400));
   renderQuests();$('quests-error').hidden=true;
   toast(t(state.quests.length?'quests_current':'quests_refreshed',{count:number(state.quests.length)}),'success');
   return;
  }
  const qIds=q=>typeof questIds==='function'?questIds(q):[q.id,...(q.variantIds||[])];const previousIds=new Set(state.quests.flatMap(qIds));
  const data=await request('/api/quests'+(refresh?'?refresh=true':''));const running=state.quests.find(q=>questMatches(q,state.session?.questId));const incoming=(data.quests||[]).filter(q=>q.kind==='play'&&q.durationSeconds===900);const newCount=previousIds.size?incoming.filter(q=>!qIds(q).some(id=>previousIds.has(id))).length:0;state.quests=incoming;if(running&&!state.quests.some(q=>questMatches(q,state.session?.questId)))state.quests.unshift({...running,unavailable:true});trackQuestUpdates(state.quests);
  if(refresh){lastQuestRefresh=Date.now();lastRealQuestFetch=Date.now();try{localStorage.setItem('lootlazy_last_quest_fetch',String(lastRealQuestFetch));}catch{}}else{lastQuestRefresh=Date.parse(data.last_synced)||0;}
  renderQuests();$('quests-error').hidden=true;if(refresh&&!silent){if(previousIds.size>0&&newCount===0)toast(t('quests_current'),'success');else if(newCount>0)toast(t('quests_new_found',{count:number(newCount)}),'success');else toast(t('quests_refreshed',{count:number(state.quests.length)}),'success');}
 }
 catch{if(refresh){state.quests=state.quests.filter(q=>questMatches(q,state.session?.questId)||Date.parse(q.expiresAt)>Date.now());renderQuests();$('quests-error').textContent=t('quests_refresh_error');$('quests-error').hidden=false;}}
 finally{questsBusy=false;busy(button,false);}
}
