async function refreshCatalog(button=$('refresh-games-btn'),silent=false){if(state.catalogBusy)return;state.catalogBusy=true;busy(button,true);try{const now=Date.now();if(!silent&&(now-lastRealCatalogFetch<15*60*1000)){await new Promise(r=>setTimeout(r,500));toast(t('games_current'),'success');return;}const data=await request('/api/refresh-catalog',{});lastRealCatalogFetch=Date.now();try{localStorage.setItem('lootlazy_last_catalog_fetch',String(lastRealCatalogFetch));}catch{}await loadStats();await fetchGames();if(state.selectedGame){const match=state.games.find(game=>game.id===state.selectedGame.id);if(match){const chosen=state.selectedExecutable;state.selectedGame=match;state.selectedExecutable=chosen||match.resolution?.primaryExecutable||'';renderSelected();renderSession();}}if(!silent)toast(t(data.changed===false?'games_current':'catalog_updated',{count:number(data.count)}),'success');}catch{if(!silent)toast(t('catalog_error'),'error');}finally{busy(button,false);state.catalogBusy=false;}}
