function renderExecutableDropdown(){const select=$('sim-executable-select'),list=$('exe-options');$('exe-value').textContent=select.selectedOptions[0]?.textContent||t('select_exe');list.replaceChildren();for(const option of select.options){if(!option.value)continue;const button=document.createElement('button');button.type='button';button.setAttribute('role','option');button.setAttribute('aria-selected',String(option.selected));const tick=document.createElement('span');tick.className='exe-tick';if(option.selected)tick.innerHTML=getIcon('check');const name=document.createElement('span');name.className='exe-name';name.textContent=option.textContent;button.append(tick,name);button.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change'));closeExecutableDropdown();$('exe-trigger').focus();};list.appendChild(button);} }
function closeExecutableDropdown(){$('exe-options').hidden=true;$('exe-trigger').setAttribute('aria-expanded','false');}
$('exe-trigger').onclick=()=>{const list=$('exe-options');list.hidden=!list.hidden;$('exe-trigger').setAttribute('aria-expanded',String(!list.hidden));};
document.addEventListener('click',event=>{if(!event.target.closest('.exe-dropdown'))closeExecutableDropdown();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeExecutableDropdown();if(event.target.closest('.exe-dropdown')&&['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();$('exe-options').hidden=false;$('exe-trigger').setAttribute('aria-expanded','true');const options=[...$('exe-options').children];const index=options.indexOf(document.activeElement);options[event.key==='Home'?0:event.key==='End'?options.length-1:Math.max(0,Math.min(options.length-1,index+(event.key==='ArrowDown'?1:-1)))]?.focus();}});

