let updatesBusy=false;
async function loadUpdates(check=false,silent=false){if(updatesBusy)return;updatesBusy=true;const button=$('btn-check-updates');if(check)busy(button,true);try{const previous=state.update?.latestVersion;state.update=await request(check?'/api/updates/check':'/api/updates',check?{}:undefined);renderUpdates();if(state.update.status==='available'&&state.update.latestVersion!==previous&&state.tab!=='settings')toast(t('update_available_version',{version:state.update.latestVersion}),'info');}catch{state.update={...(state.update||{}),status:'offline'};renderUpdates();}finally{updatesBusy=false;if(check)busy(button,false);}if(!check&&!window.lootlazyDiagnostic)loadUpdates(true,true);}
function renderUpdates(){
 const update=state.update;if(!update)return;const available=update.status==='available';
 $('updates-last-checked').textContent=update.checkedAt?dateText(update.checkedAt,true):'—';
 $('app-version').textContent='LootLazy '+(update.currentVersion||'');$('update-available-badge').hidden=!available;
 $('update-status').textContent=t(available&&update.canInstall!==true?'updates_unsigned':available?'update_available_version':update.status==='up_to_date'?'updates_current':['restricted','offline','rate_limited'].includes(update.status)?'updates_unavailable':'updates_ready',{version:update.latestVersion||''});
 $('btn-install-update').hidden=!available||update.canInstall!==true;

}







async function installUpdate(){if(state.installingUpdate)return;state.installingUpdate=true;const button=$('btn-install-update');button.disabled=true;button.textContent=t('updates_downloading');try{await request('/api/updates/install',{});button.textContent=t('updates_restarting');}catch(error){const code=['updates_stop_sessions','updates_busy','updates_unavailable','updates_download_failed','updates_checksum_failed','updates_signature_failed','updates_save_failed','updates_install_failed'].find(code=>String(error.message).includes(code));toast(t(code||'updates_install_failed'),'error');state.installingUpdate=false;button.disabled=false;button.textContent=t('install_update');}}

function renderCryptoSupport(){const currency=$('crypto-currency').value,network=$('crypto-network'),previous=network.value;const available=currency==='ETH'?['ethereum']:currency==='BNB'?['bsc']:['ethereum','bsc'];network.replaceChildren();for(const value of available){const option=document.createElement('option');option.value=value;option.textContent=value==='ethereum'?'Ethereum (ERC-20)':'BNB Smart Chain (BEP-20)';if(currency==='ETH')option.textContent='Ethereum';if(currency==='BNB')option.textContent='BNB Smart Chain';network.appendChild(option);}if(available.includes(previous))network.value=previous;$('crypto-currency-icon').src='assets/crypto/'+(currency==='ETH'?'ethereum':currency==='BNB'?'bnb':'tether')+'.svg';$('crypto-choice-label').textContent=currency+' · '+(network.value==='ethereum'?'Ethereum':'BNB Smart Chain');$('crypto-copy-status').textContent='';}
async function copyDonationAddress(){const address=$('crypto-address').textContent.trim();if(!/^0x[0-9a-fA-F]{40}$/.test(address)){toast(t('crypto_copy_failed'),'error');return;}try{try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(address);}catch{const previous=document.activeElement,area=document.createElement('textarea');area.value=address;area.style.position='fixed';area.style.top='-10000px';document.body.appendChild(area);area.select();let copied=false;try{copied=document.execCommand('copy');}finally{area.remove();previous?.focus();}if(!copied)throw Error('Clipboard denied');}$('crypto-copy-status').textContent=t('crypto_copied');}catch{$('crypto-copy-status').textContent=t('crypto_copy_failed');}}

async function loadPlatformAvailability(){try{const platforms=await request('/api/platforms/status');state.discordInstalled=platforms.discordInstalled;state.steamInstalled=platforms.steamInstalled;updateDiscordIndicator(state.discordConnected);updateSteamIndicator(state.steamRunning,state.steamConnected);}catch{}}
document.addEventListener('DOMContentLoaded',()=>{loadPlatformAvailability();document.querySelectorAll('[data-platform-download]').forEach(button=>button.onclick=async()=>{try{await request('/api/platforms/download',{platform:button.dataset.platformDownload});}catch{toast(t('download_open_failed'),'error');}});});
